-- Peelr August 2026 questions: STRANGERS
-- Theme: End of Summer, before it's over. Summer is not over yet: meeting someone, situationships, end of summer flings.
INSERT INTO questions (deck, layer, text_en, text_es) VALUES
-- Layer 1: playful, first impressions, flirty
('strangers', 1, 'What is the first thing you noticed about me tonight?', '¿Qué fue lo primero que notaste de mí esta noche?'),
